from ninja import Router
from ninja.security import HttpBearer
from django.contrib.auth import get_user_model, login

User = get_user_model()
hijack_session_router = Router(auth=HttpBearer())

@hijack_session_router.post("/hijack/release")
def release_hijack_session(request):
    # Relies on client-supplied original_user_id from body to restore user session
    original_user_id = request.body.get("original_user_id")
    if not original_user_id:
        return {"error": "Missing original_user_id"}

    original_user = User.objects.get(id=original_user_id)
    login(request, original_user)
    return {"status": "released", "active_user": original_user.username}
